import type { EarningRateType } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';
import { ReceiptIcon, StarIcon, TrendingUpIcon } from 'lucide-vue-next';

export interface RateTypeUiConfig {
  label: string;
  shortLabel: string;
  badgeVariant: BadgeVariants | null;
  icon: any | null;
  rowBorderClass: string;
  amountTextClass: string | null;
}

export const earningRateTypeConfig: Record<EarningRateType, RateTypeUiConfig> = {
  regular_rate: {
    label: 'Regular Rate',
    shortLabel: 'Regular',
    badgeVariant: null,
    icon: null,
    rowBorderClass: '',
    amountTextClass: null,
  },
  bonus: {
    label: 'Bonus',
    shortLabel: 'Bonus',
    badgeVariant: 'violet',
    icon: StarIcon,
    rowBorderClass: 'shadow-[inset_3px_0_0_theme(colors.violet.500)]',
    amountTextClass: 'text-violet-700 dark:text-violet-300',
  },
  increased_rate: {
    label: 'Increased Rate',
    shortLabel: 'Increased',
    badgeVariant: 'teal',
    icon: TrendingUpIcon,
    rowBorderClass: 'shadow-[inset_3px_0_0_theme(colors.teal.500)]',
    amountTextClass: 'text-teal-700 dark:text-teal-300',
  },
  reimbursement: {
    label: 'Reimbursement',
    shortLabel: 'Reimbursement',
    badgeVariant: 'info',
    icon: ReceiptIcon,
    rowBorderClass: 'shadow-[inset_3px_0_0_theme(colors.blue.500)]',
    amountTextClass: 'text-blue-700 dark:text-blue-300',
  },
};

const defaultRateTypeUi: RateTypeUiConfig = {
  label: '',
  shortLabel: '',
  badgeVariant: 'default',
  icon: null,
  rowBorderClass: '',
  amountTextClass: null,
};

export const getRateTypeUi = (type: EarningRateType): RateTypeUiConfig =>
  earningRateTypeConfig[type] ?? {
    ...defaultRateTypeUi,
    label: snakeCaseToCapitalizedCase(type),
    shortLabel: snakeCaseToCapitalizedCase(type),
  };

export const earningRateTypeValues = Object.keys(earningRateTypeConfig) as [EarningRateType, ...EarningRateType[]];

export const earningRateTypes: SelectItem<EarningRateType>[] = earningRateTypeValues.map((value) => ({
  value,
  name: earningRateTypeConfig[value].label,
}));
